const TYPE_CANCELLED = 'CANCELLED';
const TYPE_STARTED = 'STARTED';
const TYPE_QUEUED = 'QUEUED';
const STARTED = {
  type: TYPE_STARTED
};
const QUEUED = {
  type: TYPE_QUEUED
};
